import {test,expect,type Page} from '@playwright/test'
const origin='http://127.0.0.1:4283'
type Capture={writes:string[];failFirst:boolean;hold:boolean;release:(()=>void)|null;stale:HTMLFormElement|null}
async function openDrill(page:Page,title='Return Depth Lane',query=''){
 await page.goto(origin+'/?training-inbox-review=1'+query)
 await page.evaluate(()=>{
  const fixture:Capture={writes:[],failFirst:false,hold:false,release:null,stale:null},original=window.fetch.bind(window)
  Object.assign(window,{drillCapture:fixture})
  window.fetch=async(input,init)=>{
   const url=new URL(typeof input==='string'?input:input instanceof URL?input.href:input.url,location.href)
   if(url.pathname==='/api/player/level-up-sessions'&&init?.method==='POST'){
    fixture.writes.push(String(init.body))
    if(fixture.failFirst&&fixture.writes.length===1)return Response.json({ok:false},{status:503})
    const response=await original(input,init)
    if(fixture.hold)await new Promise<void>(resolve=>{fixture.release=resolve})
    return response
   }
   return original(input,init)
  }
 })
 await page.getByRole('button',{name:'More',exact:true}).click()
 await page.locator('[data-app-destination="coach"]').click()
 await page.locator('[data-app-destination="training"]').click()
 const training=page.getByRole('dialog',{name:'Level Up training',exact:true})
 await training.getByRole('searchbox',{name:'Find a drill',exact:true}).fill(title)
 await training.getByRole('button',{name:'Preview '+title,exact:true}).click()
 await expect(training.getByRole('heading',{name:title,exact:true})).toBeVisible()
 return training
}
const writes=(page:Page)=>page.evaluate(()=>(window as unknown as {drillCapture:Capture}).drillCapture.writes)
test.describe('Drill playbooks',()=>{
 for(const title of ['Serve Target Call','Return Depth Lane','Wall Rally Rhythm','Split-Step Rhythm','Volley Ready Split','30-30 Pressure Game'])test('shows setup and a distinct pressure routine for '+title,async({page})=>{
  const training=await openDrill(page,title)
  const choice=training.getByRole('combobox',{name:'Practice version',exact:true}),routine=training.locator('.training-drill-routine'),control=await routine.innerText()
  await expect(choice).toHaveValue('control');await expect(training.getByRole('region',{name:'Drill setup',exact:true})).toContainText('10 reps per round')
  await choice.selectOption('pressure');await expect(choice).toBeFocused();await expect(routine).not.toHaveText(control)
  if(title==='Serve Target Call')await expect(training.getByRole('region',{name:'Drill setup',exact:true})).toContainText('diagonal service box')
  if(title==='Split-Step Rhythm')await expect(training.getByRole('region',{name:'Drill setup',exact:true})).toContainText('A partner is needed')
  await training.getByRole('button',{name:'Start training',exact:true}).click()
  await expect(training.getByRole('group',{name:'Round results (optional)',exact:true})).toContainText('Add pressure')
  if(title==='Split-Step Rhythm')await expect(training.getByRole('combobox',{name:'Training context',exact:true})).toHaveValue('partner')
  await training.getByText('Review training instructions',{exact:true}).click()
  await expect(training.locator('[data-instructions] .training-drill-routine')).not.toHaveText(control)
  expect(await training.evaluate(el=>el.scrollWidth<=el.clientWidth+1)).toBe(true)
 })
 for(const width of [320,390])test('keeps raw rounds through close and confirms an applied lost save at '+width+'px',async({page},info)=>{
  await page.setViewportSize({width,height:844})
  const training=await openDrill(page,'Return Depth Lane','&training-session-lost-response=1'+(width===320?'&large=1':''))
  await training.getByRole('combobox',{name:'Practice version',exact:true}).selectOption('pressure')
  await training.getByRole('button',{name:'Start training',exact:true}).click()
  const first=training.getByRole('spinbutton',{name:'Round 1',exact:true}),second=training.getByRole('spinbutton',{name:'Round 2',exact:true}),third=training.getByRole('spinbutton',{name:'Round 3',exact:true})
  await first.fill('0');await second.fill('8');await expect(third).toHaveValue('')
  await expect(training.locator('[data-drill-tally]')).toHaveText('2 of 3 rounds recorded · 8/20 deep returns')
  await second.press('Escape');await training.getByRole('button',{name:'Keep training',exact:true}).click()
  await expect(second).toBeFocused();await expect(first).toHaveValue('0');await expect(second).toHaveValue('8');await expect(third).toHaveValue('')
  await training.getByRole('button',{name:'Resume timer',exact:true}).click()
  await page.evaluate(()=>{Object.defineProperty(document,'visibilityState',{configurable:true,value:'hidden'});document.dispatchEvent(new Event('visibilitychange'));Object.defineProperty(document,'visibilityState',{configurable:true,value:'visible'});document.dispatchEvent(new Event('visibilitychange'))})
  await expect(training.locator('[data-clock-state]')).toHaveText('Paused');await expect(second).toHaveValue('8')
  await second.scrollIntoViewIfNeeded();expect(await training.evaluate(el=>el.scrollWidth<=el.clientWidth+1)).toBe(true)
  for(const input of await training.locator('[data-drill-result]').all())expect((await input.boundingBox())!.height).toBeGreaterThanOrEqual(44)
  await page.screenshot({path:info.outputPath('drill-round-results-'+width+'.png')})
  await training.getByRole('textbox',{name:'Your training note',exact:true}).fill('Keep <finish> high.\nRecover before watching.')
  await training.getByRole('combobox',{name:'Self-rated proof (0–5)',exact:true}).selectOption('2')
  await training.getByRole('button',{name:'Save completed session',exact:true}).click()
  await expect(training.locator('[data-notice]')).toHaveText('Check whether this session saved before retrying.')
  await expect(first).toBeDisabled();await expect(second).toBeDisabled();await expect(third).toBeDisabled()
  await training.getByRole('button',{name:'Check whether this session saved',exact:true}).click()
  const latest=training.locator('.training-history-latest')
  await expect(latest).toContainText('Add pressure · Deep returns: R1 0/10; R2 8/10. Total 8/20.')
  await expect(latest).toContainText('Keep <finish> high.');await expect(latest).toContainText('2 / 5');await expect(latest.locator('finish')).toHaveCount(0)
  const bodies=await writes(page);expect(bodies).toHaveLength(1);const saved=JSON.parse(bodies[0]).session;expect(saved.rating).toBe(2);expect(saved.sharedWithCoach).toBe(false);expect(saved.note).not.toContain('R3');expect(saved).not.toHaveProperty('assignmentId')
  await latest.getByRole('button',{name:'Practice this drill again',exact:true}).click()
  await expect(training.getByRole('combobox',{name:'Practice version',exact:true})).toHaveValue('control')
  await training.getByRole('button',{name:'Start training',exact:true}).click()
  for(const field of await training.locator('[data-drill-result]').all())await expect(field).toHaveValue('')
 })
 test('retries an unapplied save with the exact frozen results and identity',async({page})=>{
  const training=await openDrill(page)
  await page.evaluate(()=>{(window as unknown as {drillCapture:Capture}).drillCapture.failFirst=true})
  await training.getByRole('button',{name:'Start training',exact:true}).click()
  await training.getByRole('spinbutton',{name:'Round 1',exact:true}).fill('9')
  await training.getByRole('combobox',{name:'Self-rated proof (0–5)',exact:true}).selectOption('3')
  await training.getByRole('button',{name:'Save completed session',exact:true}).click()
  await expect(training.locator('[data-notice]')).toHaveText('Check whether this session saved before retrying.')
  await training.getByRole('spinbutton',{name:'Round 1',exact:true}).evaluate(el=>{(el as HTMLInputElement).value='0';el.dispatchEvent(new Event('input',{bubbles:true}))})
  await training.getByRole('button',{name:'Check whether this session saved',exact:true}).click()
  await training.getByRole('button',{name:'Retry same session',exact:true}).click()
  await expect(training.locator('.training-history-latest')).toContainText('R1 9/10')
  const bodies=await writes(page);expect(bodies).toHaveLength(2);expect(bodies[1]).toBe(bodies[0])
 })
 test('rejects invalid counts before transport and preserves their correction field',async({page})=>{
  const training=await openDrill(page)
  await training.getByRole('button',{name:'Start training',exact:true}).click()
  await training.getByRole('combobox',{name:'Self-rated proof (0–5)',exact:true}).selectOption('3')
  const count=training.getByRole('spinbutton',{name:'Round 1',exact:true})
  await count.fill('11')
  await training.locator('[data-proof]').evaluate(el=>el.dispatchEvent(new Event('submit',{cancelable:true,bubbles:true})))
  await expect(training.locator('[data-notice]')).toHaveText('Use a whole number from 0 to 10 for round 1.');await expect(count).toBeFocused();await expect(count).toHaveValue('11');expect(await writes(page)).toHaveLength(0)
  await count.fill('10');await training.getByRole('button',{name:'Save completed session',exact:true}).click()
  await expect(training.locator('.training-history-latest')).toContainText('R1 10/10')
 })
 test('preserves an overlong note and round counts without truncating or sending them',async({page})=>{
  const training=await openDrill(page)
  await training.getByRole('button',{name:'Start training',exact:true}).click()
  await training.getByRole('spinbutton',{name:'Round 1',exact:true}).fill('8')
  await training.getByRole('combobox',{name:'Self-rated proof (0–5)',exact:true}).selectOption('4')
  const note=training.getByRole('textbox',{name:'Your training note',exact:true})
  await note.fill('x'.repeat(700));await training.getByRole('button',{name:'Save completed session',exact:true}).click()
  await expect(training.locator('[data-notice]')).toContainText('Shorten your note');await expect(note).toBeFocused();await expect(note).toHaveValue('x'.repeat(700));await expect(training.getByRole('spinbutton',{name:'Round 1',exact:true})).toHaveValue('8');expect(await writes(page)).toHaveLength(0)
  await note.fill('Depth held.');await training.getByRole('button',{name:'Save completed session',exact:true}).click()
  await expect(training.locator('.training-history-latest')).toContainText('R1 8/10');await expect(training.locator('.training-history-latest')).toContainText('Depth held.')
 })
 test('clears private rounds on account change and ignores a held save and detached form',async({page})=>{
  const training=await openDrill(page)
  await page.evaluate(()=>{(window as unknown as {drillCapture:Capture}).drillCapture.hold=true})
  await training.getByRole('button',{name:'Start training',exact:true}).click()
  await training.getByRole('spinbutton',{name:'Round 1',exact:true}).fill('8')
  await training.getByRole('combobox',{name:'Self-rated proof (0–5)',exact:true}).selectOption('4')
  await training.getByRole('textbox',{name:'Your training note',exact:true}).fill('private-drill-marker-8192')
  await page.evaluate(()=>{(window as unknown as {drillCapture:Capture}).drillCapture.stale=document.querySelector('[data-proof]')})
  await training.getByRole('button',{name:'Save completed session',exact:true}).click()
  await expect.poll(()=>page.evaluate(()=>Boolean((window as unknown as {drillCapture:Capture}).drillCapture.release))).toBe(true)
  await page.evaluate(()=>{(window as unknown as {switchNavigationOwner:()=>void}).switchNavigationOwner()})
  await expect(training).toHaveCount(0)
  await page.evaluate(()=>{const f=(window as unknown as {drillCapture:Capture}).drillCapture;f.stale?.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));f.release?.()})
  expect(await writes(page)).toHaveLength(1);await expect(page.getByText('private-drill-marker-8192',{exact:false})).toHaveCount(0);await expect(training).toHaveCount(0)
 })
})
